data.__transform:
(
$event := $isNilOrEmpty(data.event.name) ? " " : " : " & data.event.name;
$title := data.workcenter.code & " : " & data.mode.name & $event;

$r := $parseInt($substring(data.mode.color,1,2),16);
$g := $parseInt($substring(data.mode.color,3,4),16);
$b := $parseInt($substring(data.mode.color,5,6),16);

$color := (($r * 0.299) + ($g * 0.587) + ($b * 0.114)) > 186 ? "#000000" : "#ffffff";

"<span style=\"color:" & $color & "; font-size: 50px;font-weight: bold;\">" & $title & "</span>" 

)

(

 $c := $components.SetupForm.data.outputs.edges[0].node.workOrderProcess.code;
 $q := $components.SetupForm.data.outputs.edges[0].node.workOrderProcess.quantity;
  $d := $components.SetupForm.data.customData;

  $isNilOrEmpty($d.batchSize) 
  ? $c & " | Work Order Quantity: " & $q & " lb | Batch Size: Unset" : 

  $c & " | Work Order Quantity: " & $q & " lb | Batch Size: " & $d.batchSize & " lb" 
  )
